static void expand_tsx(cryptonote::transaction &tx);

TEST(Serialization, Transaction)
{
  tools::on_startup();
  mlog_configure(mlog_get_default_log_path("serialize_tests.log"), true);
  mlog_set_log_level(4);

  // andy 01
  std::string tx_hex = "";

  // unit tests
  // std::string tx_hex = "";

  // newest
  // std::string tx_hex = "";

  std::string tx_blob;
  CHECK_AND_ASSERT_THROW_MES(epee::string_tools::parse_hexstr_to_binbuff(tx_hex, tx_blob), "Cannot convert hex string to a binary blob");

  cryptonote::transaction tx;
  crypto::hash tx_hash {};
  crypto::hash tx_prefix_hash {};
  CHECK_AND_ASSERT_THROW_MES(cryptonote::parse_and_validate_tx_from_blob(tx_blob, tx, tx_hash, tx_prefix_hash), "Cannot deserialize the transaction");
  MDEBUG("Transaction-prefix hash: " << epee::string_tools::pod_to_hex(tx_prefix_hash));
  MDEBUG("Transaction hash: " << epee::string_tools::pod_to_hex(tx_hash));
  MDEBUG("Transaction JSON: " << cryptonote::obj_to_json_str(tx));

  expand_tsx(tx);
  bool resx = rct::verRctSemanticsSimple(tx.rct_signatures);
  // bool resy = rct::verRctNonSemanticsSimple(tx.rct_signatures);
  CHECK_AND_ASSERT_THROW_MES(resx, "Tx semantics failed");
}

static void expand_tsx(cryptonote::transaction &tx)
{
  auto & rv = tx.rct_signatures;
  if (rv.type == rct::RCTTypeFull)
  {
    rv.p.MGs.resize(1);
    rv.p.MGs[0].II.resize(tx.vin.size());
    for (size_t n = 0; n < tx.vin.size(); ++n)
      rv.p.MGs[0].II[n] = rct::ki2rct(boost::get<cryptonote::txin_to_key>(tx.vin[n]).k_image);
  }
  else if (rv.type == rct::RCTTypeSimple || rv.type == rct::RCTTypeBulletproof || rv.type == rct::RCTTypeBulletproof2)
  {
    CHECK_AND_ASSERT_THROW_MES(rv.p.MGs.size() == tx.vin.size(), "Bad MGs size");
    for (size_t n = 0; n < tx.vin.size(); ++n)
    {
      rv.p.MGs[n].II.resize(1);
      rv.p.MGs[n].II[0] = rct::ki2rct(boost::get<cryptonote::txin_to_key>(tx.vin[n]).k_image);
    }
  }
  else if (rv.type == rct::RCTTypeCLSAG || rv.type == rct::RCTTypeBulletproofPlus)
  {
    if (!tx.pruned)
    {
      CHECK_AND_ASSERT_THROW_MES(rv.p.CLSAGs.size() == tx.vin.size(), "Bad CLSAGs size");
      for (size_t n = 0; n < tx.vin.size(); ++n)
      {
        rv.p.CLSAGs[n].I = rct::ki2rct(boost::get<cryptonote::txin_to_key>(tx.vin[n]).k_image);
      }
    }
  }
  else
  {
    CHECK_AND_ASSERT_THROW_MES(false, "Unsupported rct tx type: " + boost::lexical_cast<std::string>(rv.type));
  }
}
